mapper.select:
select 'SLIP-'||replace(#{slip_date}, '-', '')||'-'||lpad(cast(count(*) + 1 as text), 4, '0') as seq
  from tb_slip_header
 where slip_date = #{slip_date}

mapper.update:
update tb_slip_header 
   set slip_date = #{slip_date}
      ,slip_type = #{slip_type}
      ,description = #{description}
      ,resolution_id = #{resolution_id}
      ,status = #{status}
      ,created_by = #{created_by}
      ,updated_at = now()
 where 1=1
   and slip_id = #{slipId}

update tb_slip_detail
   set acc_code = #{acc_code},
       dr_cr = #{dr_cr},
       amount = #{amount},
       summary = #{remark}
 where 1=1
   and slip_id = #{slip_id}
   and detail_id = #{detail_id}

mapper.delete:
delete 
  from tb_slip_detail 
 where slip_id = #{slip_id}
   and etail_id = #{detail_id}
